      reputation: { label: 'Il lit la réputation.', body: 'Une contrepartie de confiance obtient une concession plus rapide. Un portefeuille tout neuf reçoit plus de prudence.' },
      closes: { label: 'Il conclut au lieu de stagner.', body: 'Au dernier tour, si l\'offre est dans votre fourchette, votre agent accepte plutôt que de partir pour quelques dollars.' },
