    guardrails: { heading: 'Définir vos garde-fous', body: 'Votre agent agit uniquement dans les limites que vous fixez dans votre profil: votre budget ou prix demandé, votre fenêtre de livraison acceptable et votre tolérance pour s\'écarter du nombre publié. Réglez-les une fois et l\'agent les respecte à chaque transaction.' },
    guardrailsFigure: { alt: 'Le formulaire de demande affichant le budget, l\'échéance et les garde-fous de tolérance', caption: 'Les garde-fous dans lesquels votre agent négocie' },
